mapper.select:
SELECT DISTINCT ass.* FROM ( SELECT a.serial_number FROM `tech_assemble` AS a LEFT JOIN tech_assemble_detail AS ad ON a.id = ad.assemble_id WHERE ad.artifact_id IS NULL AND a.bool_delete_enum = 0 AND ad.bool_delete_enum = 0
AND a.area_id = #{areaId}
ORDER BY a.id ASC ) AS ass

SELECT *
FROM `tech_assemble`
WHERE bool_delete_enum = 0
AND assemble_config_id = #{assembleConfigId}

    AND spec_prefix = #{specPrefix}

LIMIT 1

Select serial_number, specification, quantity, length, net_weight from tech_assemble where assemble_config_id in ( SELECT id FROM sys_assemble_config WHERE bool_delete_enum = 0
and name=#{classificationName}
)
and material=#{material}
and project_id=#{projectId}
and bool_delete_enum=0

SELECT ass.* FROM tech_assemble ass, tech_assemble_detail detai WHERE detai.bool_delete_enum = 0 AND ass.bool_delete_enum = 0 AND ass.id = detai.assemble_id
AND ass.specification = #{specification}
AND detai.artifact_id = #{artifactId}
AND ass.monomer_id = #{monomerId}
AND ass.area_id = #{areaId}
ORDER BY ass.length DESC LIMIT 1

SELECT ass.* FROM tech_assemble ass, tech_assemble_detail detai WHERE detai.bool_delete_enum = 0 AND ass.bool_delete_enum = 0 AND ass.id = detai.assemble_id
AND ass.specification = #{specification}
AND ass.length=#{length}
AND detai.artifact_id IN
#{item}

SELECT assemble.id, assemble.serial_number, assemble.length, assemble.remark, assemble.specification, assemble.material, assemble.net_weight, assemble.total_net_weight, assemble.material, assemble.bool_have_NC1, assemble.assemble_config_id, assemble.production_line_type_enum, assemble.bool_main_assemble, cp.id AS 'project.id', cp.name AS 'project.name', cp.short_name AS 'project.shortName', pm.id AS 'monomer.id', pm.name AS 'monomer.name', pa.id AS 'area.id', pa.name AS 'area.name', tad.id AS assembleDetailId, tad.quantity * ta.quantity AS quantity, tad.quantity AS proportionality, ta.id AS 'artifactTypesettingDTO.id', ta.serial_number AS 'artifactTypesettingDTO.serialNumber', ta.quantity AS 'artifactTypesettingDTO.artifactQuantity', ssc.id AS 'artifactTypesettingDTO.structureClassId', ssc.classification_name AS 'artifactTypesettingDTO.classificationName' FROM tech_assemble assemble INNER JOIN tech_assemble_detail tad on tad.assemble_id = assemble.id and tad.bool_delete_enum = 0 INNER JOIN tech_artifact ta on ta.id = tad.artifact_id and ta.bool_delete_enum = 0 left join contract_project cp on cp.id = assemble.project_id left join plan_monomer pm on pm.id = assemble.monomer_id left join plan_area pa on pa.id = assemble.area_id LEFT JOIN sys_structure_classification ssc on ssc.id = ta.structure_class_id WHERE assemble.bool_delete_enum = 0 and assemble.project_id = #{projectId}
and assemble.production_line_type_enum = #{productionLineTypeEnum}
and ta.structure_class_id in
#{structureClassId}
AND assemble.length >= 300
AND assemble.monomer_id = #{monomerId}
and assemble.area_id in
#{areaId}
AND assemble.bool_main_assemble = #{boolMainAssemble}
AND assemble.spec_prefix = #{specPrefix}
AND assemble.specification = #{specification}
AND assemble.material = #{material}
AND assemble.serial_number = #{serialNumber}
AND assemble.length >= #{length}
AND assemble.bool_have_nc1 = #{boolHaveNC1}
order by assemble.bool_have_nc1 ASC
,assemble.length desc
,assemble.length ASC

SELECT assemble.id, assemble.serial_number, assemble.length, assemble.remark, assemble.specification, assemble.material, assemble.net_weight, assemble.total_net_weight, assemble.material, assemble.bool_have_NC1, assemble.assemble_config_id, assemble.production_line_type_enum, assemble.bool_main_assemble, cp.id AS 'project.id', cp.name AS 'project.name', cp.short_name AS 'project.shortName', pm.id AS 'monomer.id', pm.name AS 'monomer.name', pa.id AS 'area.id', pa.name AS 'area.name', tad.id AS assembleDetailId, noNesting.quantity AS quantity, ta.id AS 'artifactTypesettingDTO.id', ta.serial_number AS 'artifactTypesettingDTO.serialNumber', ssc.id AS 'artifactTypesettingDTO.structureClassId', ssc.classification_name AS 'artifactTypesettingDTO.classificationName' FROM tech_assemble assemble INNER JOIN tech_assemble_detail tad on tad.assemble_id = assemble.id INNER JOIN mes_building_assemble_no_nesting noNesting on noNesting.assemble_detail_id = tad.id and noNesting.bool_delete_enum = 0 INNER JOIN tech_artifact ta on ta.id = tad.artifact_id and ta.bool_delete_enum = 0 left join contract_project cp on cp.id = assemble.project_id left join plan_monomer pm on pm.id = assemble.monomer_id left join plan_area pa on pa.id = assemble.area_id LEFT JOIN sys_structure_classification ssc on ssc.id = ta.structure_class_id WHERE assemble.bool_delete_enum = 0 and assemble.project_id = #{projectId} and assemble.production_line_type_enum = #{productionLineTypeEnum} and assemble.produced_quantity < assemble.quantity
AND assemble.monomer_id = #{monomerId}
and assemble.area_id in
#{areaId}
AND assemble.spec_prefix = #{specPrefix}
AND assemble.specification = #{specification}
AND assemble.material = #{material}
AND assemble.serial_number = #{serialNumber}
AND assemble.length >= #{length}

SELECT DISTINCT ssc.id, ssc.classification_name, ssc.definition_word, assemble.id As assembleId FROM tech_assemble assemble INNER JOIN tech_assemble_detail tad on tad.assemble_id = assemble.id and tad.bool_delete_enum = 0 INNER JOIN tech_artifact ta on ta.id = tad.artifact_id and ta.bool_delete_enum = 0 LEFT JOIN sys_structure_classification ssc on ssc.id = ta.structure_class_id WHERE assemble.bool_delete_enum = 0 and assemble.project_id = #{projectId} and assemble.monomer_id = #{monomerId} and assemble.production_line_type_enum = #{productionLineTypeEnum}
and assemble.area_id in
#{areaId}
and ta.structure_class_id in
#{structureClassId}
AND assemble.length > 760

SELECT detai.artifact_id 'id', detai.assemble_id 'assembleOrPartid', detai.quantity 'scale', ass.produced_quantity 'producedQuantity', (ass.produced_quantity-ass.used_quantity) DIV detai.quantity 'complete' FROM tech_assemble ass, tech_assemble_detail detai WHERE detai.bool_delete_enum = 0 AND ass.bool_delete_enum = 0 AND ass.bool_process=1 AND ass.id = detai.assemble_id
AND detai.artifact_id IN
#{item}

select ta.*, 16 As productType, pa.name AS areaName, m.name AS monomerName from tech_assemble ta LEFT JOIN plan_area pa on pa.id = ta.area_id LEFT JOIN plan_monomer m on m.id = ta.monomer_id where ta.bool_delete_enum = 0
AND ta.area_id in
#{areaId}
AND ta.monomer_id = #{monomerId}
and ta.serial_number = #{serialNumber}
limit 1

select a.* from ( select a.id, a.`name`, a.specification, a.serial_number, GROUP_CONCAT( DISTINCT b.number ) number, a.create_time, c.id 'project.id', c.name 'project.name', c.serial_number 'project.serial_number', c.short_name 'project.short_name', d.id 'monomer.id', d.name 'monomer.name', e.id 'area.id', e.name 'area.name' from tech_assemble a left join mes_building_produce_team_report b on a.id = b.product_id left join contract_project c on a.project_id = c.id left join plan_monomer d on a.monomer_id = d.id left join plan_area e on a.area_id = e.id where a.bool_delete_enum = 0 and b.bool_delete_enum = 0 and b.task_type_enum = 16 and a.production_line_type_enum = 1 and a.serial_number like concat( '%', #{serialNumber}, '%' )
and a.project_id = #{projectId}
and a.monomer_id = #{monomerId}
and a.area_id = #{areaId}
group by a.id, c.id, d.id, e.id, a.serial_number, a.specification ) a order by CHAR_LENGTH( a.serial_number ), a.create_time desc
